def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def target_value(N):
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4, 5]
results = {}

for N in N_values:
    S_N = calculate_S(N)
    T_N = target_value(N)
    condition_met = S_N == T_N
    results[N] = {
        "S(N)": S_N,
        "Target": T_N,
        "Condition Met": condition_met
    }

for N, res in results.items():
    print(f"N={N}: S(N) = {res['S(N)']}, Target = {res['Target']}, Matches = {res['Condition Met']}")

